.validation-message {
  font-size: 0.8125rem;
  color: var(--text-error);
  font-weight: 500;
  line-height: 1.4;
  min-height: 0;
  display: none; /* shown via JS */
}
.validation-message.visible { display: block; }
.validation-message.success  { color: var(--text-success); }

