  --text-primary:   #e8eaf0;
  --text-secondary: #8b90a0;
  --text-label:     #c5c9d6;
  --text-error:     #ff7b85;
  --text-success:   #3ecf8e;
  --text-hint:      #6e7485;

  --accent:         #6c8eff;
  --accent-hover:   #849fff;
  --accent-active:  #5a7aee;

  --required:       #ff7b85;

  --radius-sm:  6px;
  --radius-md:  10px;
  --radius-lg:  16px;

  --shadow-card: 0 8px 32px rgba(0, 0, 0, 0.55);
  --shadow-btn:  0 4px 16px rgba(108, 142, 255, 0.35);

  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --transition: 180ms ease;
}

/* ── Reset / Base ──────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-primary);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  line-height: 1.6;
}

/* ── Skip link ─────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Header ────────────────────────────────────────────────────────────── */
header {
  border-bottom: 1px solid var(--border);
  padding: 0.875rem 1.5rem;
  background: rgba(22, 25, 32, 0.85);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}
.header-inner {
  max-width: 900px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}
.logo {
  font-size: 1.5rem;
  color: var(--accent);
  line-height: 1;
}
.site-name {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

/* ── Main layout ───────────────────────────────────────────────────────── */
main {
  flex: 1;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 3rem 1rem 4rem;
}

.form-section { width: 100%; max-width: 520px; }

/* ── Card ──────────────────────────────────────────────────────────────── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow-card);
}

h1 {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  margin-bottom: 0.375rem;
}

.form-intro {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
}

/* ── Form fields ───────────────────────────────────────────────────────── */
form { display: flex; flex-direction: column; gap: 1.375rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-label);
  letter-spacing: 0.01em;
}

.required-indicator { color: var(--required); margin-left: 0.125rem; }

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.6875rem 0.875rem;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.9375rem;
  outline: none;
  transition: border-color var(--transition), background var(--transition),
