/* Focus outline fallback for forced-colors */
input:focus { outline: 2px solid transparent; outline-offset: 2px; }
@media (forced-colors: active) {
  input:focus { outline: 2px solid ButtonText; }
}

/* Valid state */
input.is-valid {
  border-color: var(--border-success);
}
input.is-valid:focus {
  box-shadow: 0 0 0 3px rgba(62, 207, 142, 0.18);
}

/* Error state */
input.is-error {
