  box-shadow: 0 0 0 3px rgba(255, 95, 109, 0.2);
}

/* ── Helper / validation text ──────────────────────────────────────────── */
.helper-text {
  font-size: 0.8125rem;
  color: var(--text-hint);
  line-height: 1.4;
}

.validation-message {
  font-size: 0.8125rem;
