.validation-message.visible { display: block; }
.validation-message.success  { color: var(--text-success); }

/* ── Required note ─────────────────────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-top: -0.25rem;
}
.required-note span { color: var(--required); }

/* ── Form-level status ─────────────────────────────────────────────────── */
.form-status {
  font-size: 0.9375rem;
  font-weight: 500;
