// Accepts: +1 (555) 000-0000 | 555-000-0000 | (555) 000-0000 | 5550000000 | +15550000000
const PHONE_RE = /^(\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}$/;

function $(selector, root = document) {
  return root.querySelector(selector);
