// ── Field component ──────────────────────────────────────────────────────────

/**
 * Creates a stateful field controller.
 * @param {object} config
 */
function createField({ inputId, errorId, validate }) {
  const input = document.getElementById(inputId);
  const errorEl = document.getElementById(errorId);

  function showError(msg) {
    errorEl.textContent = msg;
    errorEl.classList.add("visible");
    errorEl.classList.remove("success");
    input.classList.add("is-error");
    input.classList.remove("is-valid");
    input.setAttribute("aria-invalid", "true");
  }

  function showSuccess() {
    errorEl.textContent = "";
    errorEl.classList.remove("visible", "success");
    input.classList.remove("is-error");
    input.classList.add("is-valid");
    input.removeAttribute("aria-invalid");
  }

  function clearState() {
    errorEl.textContent = "";
    errorEl.classList.remove("visible", "success");
    input.classList.remove("is-error", "is-valid");
    input.removeAttribute("aria-invalid");
  }

  /** Returns true when field is valid */
  function runValidation(showFeedback = true) {
    const result = validate(input.value.trim());
    if (result === true) {
      if (showFeedback) showSuccess();
      return true;
    }
    if (showFeedback) showError(result);
    return false;
  }

  // Validate on blur (first interaction)
  let touched = false;
  input.addEventListener("blur", () => {
    touched = true;
    runValidation();
  });

  // Re-validate on input once field has been touched
  input.addEventListener("input", () => {
    if (touched) runValidation();
  });

  return { input, runValidation, showError, clearState };
}

// ── Validation rules ─────────────────────────────────────────────────────────

function validateFullName(value) {
  if (!value) return "Full name is required.";
  if (value.length < 2) return "Please enter at least 2 characters.";
  return true;
}

function validateEmail(value) {
  if (!value) return "Email address is required.";
  if (!EMAIL_RE.test(value)) return "Please enter a valid email address (e.g. you@example.com).";
  return true;
}

function validatePhone(value) {
  if (!value) return true; // optional
  if (!PHONE_RE.test(value))
    return "Please enter a valid phone number (e.g. +1 (555) 000-0000 or 555-000-0000).";
  return true;
}

// ── Form component ───────────────────────────────────────────────────────────

function ContactForm() {
  const form     = document.getElementById("contact-form");
  const statusEl = document.getElementById("form-status");

  const fields = {
    name:  createField({ inputId: "full-name", errorId: "full-name-error", validate: validateFullName }),
    email: createField({ inputId: "email",     errorId: "email-error",     validate: validateEmail }),
    phone: createField({ inputId: "phone",     errorId: "phone-error",     validate: validatePhone }),
  };

  function setStatus(msg, type /* "success" | "error-summary" */) {
    statusEl.textContent = msg;
    statusEl.className = `form-status visible ${type}`;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "form-status";
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    clearStatus();

    // Validate all fields, collect results
    const results = Object.values(fields).map((f) => f.runValidation(true));
    const allValid = results.every(Boolean);

    if (!allValid) {
      setStatus("Please fix the errors above before submitting.", "error-summary");
      // Focus first invalid field
      for (const field of Object.values(fields)) {
        if (field.input.classList.contains("is-error")) {
          field.input.focus();
          break;
        }
      }
      return;
    }

    // Simulate async submission
    const btn = $(".submit-btn", form);
    btn.disabled = true;
    btn.textContent = "Sending…";

    setTimeout(() => {
      btn.disabled = false;
      btn.textContent = "Send Message";

      // Clear form
      form.reset();
      Object.values(fields).forEach((f) => f.clearState());

      setStatus("✓ Message sent! We'll be in touch within one business day.", "success");
    }, 1200);
  });
}

